package clusterdata.datatypes;

import java.io.Serializable;

public class TaskEvent implements Serializable {

    // Event type constants
    public static final int SUBMIT = 0;
    public static final int SCHEDULE = 1;
    public static final int EVICT = 2;
    public static final int FAIL = 3;
    public static final int FINISH = 4;
    public static final int KILL = 5;
    public static final int LOST = 6;
    public static final int UPDATE_PENDING = 7;
    public static final int UPDATE_RUNNING = 8;

    private long timestamp;
    private String missingInfo;
    private long jobId;
    private long taskIndex;
    private String machineId;
    private int eventType;
    private String user;
    private int schedulingClass;
    private int priority;
    private double cpuRequest;
    private double memRequest;
    private double diskRequest;
    private int differentMachinesRestriction;

    public TaskEvent() {
    }

    public TaskEvent(long timestamp, String missingInfo, long jobId, long taskIndex, String machineId,
                     int eventType, String user, int schedulingClass, int priority,
                     double cpuRequest, double memRequest, double diskRequest, int differentMachinesRestriction) {
        this.timestamp = timestamp;
        this.missingInfo = missingInfo;
        this.jobId = jobId;
        this.taskIndex = taskIndex;
        this.machineId = machineId;
        this.eventType = eventType;
        this.user = user;
        this.schedulingClass = schedulingClass;
        this.priority = priority;
        this.cpuRequest = cpuRequest;
        this.memRequest = memRequest;
        this.diskRequest = diskRequest;
        this.differentMachinesRestriction = differentMachinesRestriction;
    }

    public static TaskEvent fromString(String line) {
        String[] tokens = line.split(",", -1);
        if (tokens.length < 13) {
            return null;
        }
        try {
            long timestamp = tokens[0].isEmpty() ? 0 : Long.parseLong(tokens[0]);
            String missingInfo = tokens[1];
            long jobId = tokens[2].isEmpty() ? -1 : Long.parseLong(tokens[2]);
            long taskIndex = tokens[3].isEmpty() ? -1 : Long.parseLong(tokens[3]);
            String machineId = tokens[4];
            int eventType = tokens[5].isEmpty() ? -1 : Integer.parseInt(tokens[5]);
            String user = tokens[6];
            int schedulingClass = tokens[7].isEmpty() ? 0 : Integer.parseInt(tokens[7]);
            int priority = tokens[8].isEmpty() ? 0 : Integer.parseInt(tokens[8]);
            double cpuRequest = tokens[9].isEmpty() ? 0.0 : Double.parseDouble(tokens[9]);
            double memRequest = tokens[10].isEmpty() ? 0.0 : Double.parseDouble(tokens[10]);
            double diskRequest = tokens[11].isEmpty() ? 0.0 : Double.parseDouble(tokens[11]);
            int differentMachinesRestriction = tokens[12].isEmpty() ? 0 : Integer.parseInt(tokens[12]);

            return new TaskEvent(timestamp, missingInfo, jobId, taskIndex, machineId, eventType,
                    user, schedulingClass, priority, cpuRequest, memRequest, diskRequest, differentMachinesRestriction);
        } catch (Exception e) {
            return null;
        }
    }

    public long getTimestamp() {
        return timestamp;
    }

    public void setTimestamp(long timestamp) {
        this.timestamp = timestamp;
    }

    public String getMissingInfo() {
        return missingInfo;
    }

    public void setMissingInfo(String missingInfo) {
        this.missingInfo = missingInfo;
    }

    public long getJobId() {
        return jobId;
    }

    public void setJobId(long jobId) {
        this.jobId = jobId;
    }

    public long getTaskIndex() {
        return taskIndex;
    }

