        this.eventType = eventType;
    }

    public String getUser() {
        return user;
    }

    public void setUser(String user) {
        this.user = user;
    }

    public int getSchedulingClass() {
        return schedulingClass;
    }

    public void setSchedulingClass(int schedulingClass) {
        this.schedulingClass = schedulingClass;
    }

    public int getPriority() {
        return priority;
    }

    public void setPriority(int priority) {
        this.priority = priority;
    }

    public double getCpuRequest() {
        return cpuRequest;
    }

    public void setCpuRequest(double cpuRequest) {
        this.cpuRequest = cpuRequest;
    }

    public double getMemRequest() {
        return memRequest;
    }

    public void setMemRequest(double memRequest) {
        this.memRequest = memRequest;
    }

    public double getDiskRequest() {
        return diskRequest;
    }

